#!/usr/bin/env node
/**
 * Embed the native local-runner files (native-host/* + runLocal/*) into a generated TS
 * module so the extension can serve them to users as a downloadable zip — no external host
 * or backend. Run automatically before each build (see package.json "prebuild"-style hook).
 *
 * Bundle layout (flat, matches apitiser-runner.mjs's runLocal resolver):
 *   apitiser-runner.mjs, install.sh, INSTALL.md   (from native-host/)
 *   runLocal/...                                   (the runLocal tool)
 */
import { readFileSync, readdirSync, statSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const repoParent = path.resolve(root, '..');

const NATIVE_HOST_FILES = ['apitiser-runner.mjs', 'install.sh', 'install.ps1', 'INSTALL.md'];
const isExec = (p) => /\.(sh|mjs)$/.test(p);

const walk = (dir, baseInBundle) => {
  const out = [];
  for (const entry of readdirSync(dir)) {
    if (entry === '.git' || entry === 'node_modules' || entry === '.DS_Store') continue;
    const full = path.join(dir, entry);
    const bundlePath = baseInBundle ? `${baseInBundle}/${entry}` : entry;
    if (statSync(full).isDirectory()) {
      out.push(...walk(full, bundlePath));
    } else {
      out.push({ path: bundlePath, content: readFileSync(full, 'utf8'), exec: isExec(bundlePath) });
    }
  }
  return out;
};

const files = [];

// native-host → bundle root
const nativeHostDir = path.join(root, 'native-host');
for (const name of NATIVE_HOST_FILES) {
  const full = path.join(nativeHostDir, name);
  if (!existsSync(full)) {
    throw new Error(`Missing native-host file: ${full}`);
  }
  files.push({ path: name, content: readFileSync(full, 'utf8'), exec: isExec(name) });
}

// runLocal → bundle runLocal/
const runLocalDir = path.join(repoParent, 'runLocal');
if (!existsSync(runLocalDir)) {
  throw new Error(`runLocal not found at ${runLocalDir}. Place runLocal/ next to this repo before building.`);
}
files.push(...walk(runLocalDir, 'runLocal'));

// Bundle version — bump this whenever the host/installer changes so the downloaded zip and
// its unzipped folder get a NEW name (avoids users re-running a stale installer in an old
// folder). Independent of runLocal's own VERSION.
const BUNDLE_VERSION = '1.8.0';
const runLocalVersion = existsSync(path.join(runLocalDir, 'VERSION'))
  ? readFileSync(path.join(runLocalDir, 'VERSION'), 'utf8').trim()
  : 'dev';
const version = BUNDLE_VERSION;

const outDir = path.join(root, 'src', 'shared', 'generated');
mkdirSync(outDir, { recursive: true });
const outFile = path.join(outDir, 'runnerBundle.ts');

const body = `// AUTO-GENERATED by scripts/gen-runner-bundle.mjs — do not edit by hand.
// Embeds the native local-runner so the extension can serve it as a download (no backend).

export interface RunnerFile {
  path: string;
  content: string;
  /** Whether the file should be marked executable in the zip (scripts/host). */
  exec: boolean;
}

export const RUNNER_VERSION = ${JSON.stringify(version)};

export const RUNNER_FILES: RunnerFile[] = ${JSON.stringify(files, null, 2)};
`;

writeFileSync(outFile, body, 'utf8');
console.log(`Wrote ${outFile} (${files.length} files, bundle v${BUNDLE_VERSION}, runLocal v${runLocalVersion}).`);
